import "core-js/modules/es7.array.includes";
import "core-js/modules/es6.string.includes";
/**
 * 全站http配置
 *
 * axios参数说明
 * isSerialize是否开启form表单提交
 * isToken是否需要token
 */
import axios from 'axios';
import store from '@/store/';
import router from '@/router/router';
import { serialize } from '@/util/util';
import { getToken } from '@/util/auth';
import { Message } from 'element-ui';
import website from '@/config/website';
import NProgress from 'nprogress'; // progress bar
import 'nprogress/nprogress.css'; // progress bar style
import { Base64 } from 'js-base64';
import crypto from "@/util/crypto";
import secureUtil from "@/util/secureUtil";
// 如果请求超过 `timeout` 的时间，请求将被中断 axios的默认timeout值是0,表示没有超时限制
axios.defaults.timeout = 0;
//返回其他状态吗

axios.defaults.validateStatus = function (status) {
  return status >= 200 && status <= 500; // 默认的
};
//跨域请求，允许保存cookie
axios.defaults.withCredentials = true;
// NProgress Configuration
NProgress.configure({
  showSpinner: false
});
//HTTPrequest拦截
axios.interceptors.request.use(function (config) {
  NProgress.start(); // start progress bar
  var meta = config.meta || {};
  var isToken = meta.isToken === false;
  config.headers['Authorization'] = "Basic ".concat(Base64.encode("".concat(website.clientId, ":").concat(website.clientSecret)));
  //headers传递token是否加密
  var cryptoToken = config.cryptoToken === true;
  var token = getToken();
  if (token && !isToken) {
    config.headers['Idevelop-Auth'] = cryptoToken ? 'crypto ' + crypto.encryptBySM4CBC(token) : 'bearer ' + token;
  }
  //headers中配置serialize为true开启序列化
  if (config.method === 'post' && meta.isSerialize === true) {
    config.data = serialize(config.data);
  }
  // // 完整性处理
  // secureUtil.toReqIntegrity(config)
  // // 对请求参数加密处理
  // secureUtil.reqCrypto(config);
  return config;
}, function (error) {
  return Promise.reject(error);
});
//HTTPresponse拦截
axios.interceptors.response.use(function (res) {
  NProgress.done();
  // // 对响应参数解密处理
  // secureUtil.resCrypto(res);
  var status = res.data.code || 200;
  var statusWhiteList = website.statusWhiteList || [];
  var message = res.data.msg || '未知错误';
  // 二进制数据则直接返回

  if (res.config.responseType === 'blob' || res.config.responseType === 'arraybuffer') {
    return res.data;
  }
  //如果在白名单里则自行catch逻辑处理
  if (statusWhiteList.includes(status)) return Promise.reject(res);
  //如果是401则跳转到登录页面
  if (status === 401) store.dispatch('FedLogOut').then(function () {
    return router.push({
      path: '/login'
    });
  });
  // 如果请求为非200否者默认统一处理
  if (status !== 200 && status !== 10000 && status !== 1) {
    Message({
      message: message,
      type: 'error'
    });
    return Promise.reject(new Error(message));
  }
  return res.data;
}, function (error) {
  NProgress.done();
  return Promise.reject(new Error(error));
});
export default axios;
